import argparse, json, socket, sys, time, traceback, uuid

TIMEOUT = 5.0


class Resp:
    def __init__(self, host, port, timeout=TIMEOUT):
        self.s = socket.create_connection((host, port), timeout=timeout)
        self.buf = b""

    def close(self):
        try:
            self.s.close()
        except OSError:
            pass

    @staticmethod
    def encode(*args):
        out = b"*%d\r\n" % len(args)
        for a in args:
            a = a if isinstance(a, bytes) else str(a).encode()
            out += b"$%d\r\n%s\r\n" % (len(a), a)
        return out

    def send(self, *args):
        self.s.sendall(self.encode(*args))

    def _fill(self):
        d = self.s.recv(65536)
        if not d:
            raise ConnectionError("connection closed by server")
        self.buf += d

    def _line(self):
        while b"\r\n" not in self.buf:
            self._fill()
        line, self.buf = self.buf.split(b"\r\n", 1)
        return line

    def read(self):
        line = self._line()
        t, rest = line[:1], line[1:]
        if t == b"+":
            return ("simple", rest)
        if t == b"-":
            return ("error", rest)
        if t == b":":
            return ("int", int(rest))
        if t == b"$":
            n = int(rest)
            if n == -1:
                return ("nil", None)
            while len(self.buf) < n + 2:
                self._fill()
            data, tail, self.buf = self.buf[:n], self.buf[n:n + 2], self.buf[n + 2:]
            if tail != b"\r\n":
                raise ValueError("bulk not terminated by CRLF")
            return ("bulk", data)
        raise ValueError("unexpected reply type: %r" % line[:80])

    def cmd(self, *args):
        self.send(*args)
        return self.read()


